namespace sv_28f77283ea224006a73c7359a7b3a33d.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@* Vertical sidebar navigation for settings sections *@

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link settings-nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="settings-nav-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    height: 100%;
}

.settings-nav-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    color: #495057;
    font-size: 0.95rem;
    text-align: left;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.1rem;
}

@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Profile Settings</h3>
    <p class="text-muted mb-4">Manage your personal information and how others see you.</p>

    @if (Profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="EditDisplayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="EditEmail" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="avatar-preview-area text-center">
                    <label class="form-label fw-semibold d-block">Avatar Preview</label>
                    <div class="avatar-frame mb-2">
                        @if (!string.IsNullOrWhiteSpace(EditAvatarUrl))
                        {
                            <img src="@EditAvatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <small class="text-muted text-break">@EditAvatarUrl</small>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditDisplayName = "";
    private string EditEmail = "";
    private string EditAvatarUrl = "";
    private string EditBio = "";
    private string? statusMessage;
    private bool isError;
    private bool saving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !saving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        EditDisplayName = Profile!.DisplayName;
        EditEmail = Profile.Email;
        EditAvatarUrl = Profile.AvatarUrl;
        EditBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(EditDisplayName, EditEmail, EditAvatarUrl, EditBio);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile. Please try again.";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        LoadFromProfile();
        statusMessage = null;
    }
}

.avatar-frame {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

.avatar-preview-area {
    padding: 1rem;
    border: 1px dashed #dee2e6;
    border-radius: 0.5rem;
    background: #fdfdfe;
}

@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Notification Preferences</h3>
    <p class="text-muted mb-4">Choose how and when you want to be notified.</p>

    @if (Prefs is not null)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Delivery Methods</h5>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                           checked="@editEmail" @onchange="e => editEmail = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">
                        <strong>Email Notifications</strong>
                        <br /><small class="text-muted">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                           checked="@editPush" @onchange="e => editPush = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">
                        <strong>Push Notifications</strong>
                        <br /><small class="text-muted">Receive push notifications on your devices</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                           checked="@editDigest" @onchange="e => editDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">
                        <strong>Weekly Digest</strong>
                        <br /><small class="text-muted">Get a weekly summary of activity</small>
                    </label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Muted Channels</h5>
                <p class="text-muted small">Uncheck a channel to mute notifications from it.</p>

                @if (AvailableChannels.Count > 0)
                {
                    @foreach (var channel in AvailableChannels)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@(!editMuted.Contains(channel))"
                                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                        </div>
                    }
                }
                else
                {
                    <p class="text-muted fst-italic">No channels available.</p>
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = new();
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool editEmail;
    private bool editPush;
    private bool editDigest;
    private HashSet<string> editMuted = new();
    private bool saving;
    private string? statusMessage;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !saving)
        {
            editEmail = Prefs.EmailNotifications;
            editPush = Prefs.PushNotifications;
            editDigest = Prefs.WeeklyDigest;
            editMuted = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool enabled)
    {
        if (enabled)
            editMuted.Remove(channel);
        else
            editMuted.Add(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(editEmail, editPush, editDigest, editMuted.ToList());
            await OnSave.InvokeAsync(updated);
            statusMessage = "Notification preferences saved!";
        }
        finally
        {
            saving = false;
        }
    }
}

