toolArgs.file_text:
@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Profile Settings</h3>
    <p class="text-muted mb-4">Manage your personal information and how others see you.</p>

    @if (Profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="EditDisplayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="EditEmail" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="avatar-preview-area text-center">
                    <label class="form-label fw-semibold d-block">Avatar Preview</label>
                    <div class="avatar-frame mb-2">
                        @if (!string.IsNullOrWhiteSpace(EditAvatarUrl))
                        {
                            <img src="@EditAvatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <small class="text-muted text-break">@EditAvatarUrl</small>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditDisplayName = "";
    private string EditEmail = "";
    private string EditAvatarUrl = "";
    private string EditBio = "";
    private string? statusMessage;
    private bool isError;
    private bool saving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !saving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        EditDisplayName = Profile!.DisplayName;
        EditEmail = Profile.Email;
        EditAvatarUrl = Profile.AvatarUrl;
        EditBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(EditDisplayName, EditEmail, EditAvatarUrl, EditBio);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile. Please try again.";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        LoadFromProfile();
        statusMessage = null;
    }
}

