toolArgs.file_text:
@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Notification Preferences</h3>
    <p class="text-muted mb-4">Choose how and when you want to be notified.</p>

    @if (Prefs is not null)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Delivery Methods</h5>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                           checked="@editEmail" @onchange="e => editEmail = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">
                        <strong>Email Notifications</strong>
                        <br /><small class="text-muted">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                           checked="@editPush" @onchange="e => editPush = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">
                        <strong>Push Notifications</strong>
                        <br /><small class="text-muted">Receive push notifications on your devices</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                           checked="@editDigest" @onchange="e => editDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">
                        <strong>Weekly Digest</strong>
                        <br /><small class="text-muted">Get a weekly summary of activity</small>
                    </label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Muted Channels</h5>
                <p class="text-muted small">Uncheck a channel to mute notifications from it.</p>

                @if (AvailableChannels.Count > 0)
                {
                    @foreach (var channel in AvailableChannels)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@(!editMuted.Contains(channel))"
                                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                        </div>
                    }
                }
                else
                {
                    <p class="text-muted fst-italic">No channels available.</p>
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = new();
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool editEmail;
    private bool editPush;
    private bool editDigest;
    private HashSet<string> editMuted = new();
    private bool saving;
    private string? statusMessage;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !saving)
        {
            editEmail = Prefs.EmailNotifications;
            editPush = Prefs.PushNotifications;
            editDigest = Prefs.WeeklyDigest;
            editMuted = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool enabled)
    {
        if (enabled)
            editMuted.Remove(channel);
        else
            editMuted.Add(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(editEmail, editPush, editDigest, editMuted.ToList());
            await OnSave.InvokeAsync(updated);
            statusMessage = "Notification preferences saved!";
        }
        finally
        {
            saving = false;
        }
    }
}

