arguments.file_text:
@if (Visible)
{
    <div class="modal-backdrop show" @onclick="Cancel"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@DeviceName</strong>?</p>
                    <p class="text-muted small">This will immediately sign out that device.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title mb-3">Active Sessions</h5>

        @if (Sessions is not null && Sessions.Count > 0)
        {
            <div class="table-responsive">
                <table class="table table-hover align-middle mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Sessions)
                        {
                            <tr>
                                <td>
                                    <span class="fw-semibold">@session.Device</span>
                                    @if (session.Id == CurrentSessionId)
                                    {
                                        <span class="badge bg-success ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM dd, yyyy h:mm tt")</td>
                                <td class="text-end">
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => RequestRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="text-muted fst-italic">No active sessions found.</p>
        }
    </div>
</div>

<RevokeSessionDialog Visible="@showDialog"
                     DeviceName="@(pendingSession?.Device ?? "")"
                     OnConfirm="ConfirmRevoke"
                     OnCancel="CancelRevoke" />

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private bool showDialog;
    private ActiveSession? pendingSession;

    private void RequestRevoke(ActiveSession session)
    {
        pendingSession = session;
        showDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (pendingSession is not null)
        {
            await OnRevoke.InvokeAsync(pendingSession.Id);
        }
        showDialog = false;
        pendingSession = null;
    }

    private void CancelRevoke()
    {
        showDialog = false;
        pendingSession = null;
    }
}

@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Security Settings</h3>
    <p class="text-muted mb-4">Manage your account security, passwords, and active sessions.</p>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    @if (Security is not null)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Two-Factor Authentication</h5>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                               checked="@Security.TwoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">
                            <strong>Two-Factor Authentication</strong>
                        </label>
                    </div>
                    <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                        @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                @if (Security.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">
                        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </p>
                }
            </div>
        </div>

        <ActiveSessionsTable Sessions="@Security.Sessions"
                             CurrentSessionId="@CurrentSessionId"
                             OnRevoke="OnRevokeSession" />
    }
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string current, string newPwd)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
}

@using sv_28f77283ea224006a73c7359a7b3a33d.Models

<div class="settings-section">
    <h3 class="settings-section-title">Appearance Settings</h3>
    <p class="text-muted mb-4">Customize how the application looks and feels.</p>

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Theme</h5>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")"
                                       checked="@(editTheme == theme)"
                                       @onchange="() => editTheme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Font Size</h5>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")"
                                       checked="@(editFontSize == size)"
                                       @onchange="() => editFontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Language</h5>
                        <select class="form-select" @bind="editLanguage">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                            <option value="pt">Portuguese</option>
                        </select>
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                                   checked="@editCompact" @onchange="e => editCompact = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br /><small class="text-muted">Reduce spacing and padding for denser layouts</small>
                            </label>
                        </div>
                    </div>
                </div>

                @if (!string.IsNullOrEmpty(statusMessage))
                {
                    <div class="alert alert-success alert-dismissible fade show" role="alert">
                        @statusMessage
                        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
                    </div>
                }

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                    @if (saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <h5 class="mb-0">Live Preview</h5>
                    </div>
                    <div class="card-body preview-area @PreviewThemeClass"
                         style="font-size: @PreviewFontSize; padding: @(editCompact ? "0.5rem" : "1.25rem");">
                        <h6 style="margin-bottom: @(editCompact ? "0.25rem" : "0.75rem");">
                            Sample Heading
                        </h6>
                        <p style="margin-bottom: @(editCompact ? "0.25rem" : "0.75rem");">
                            This is a preview of how your content will appear with the current settings.
                        </p>
                        <div class="d-flex gap-2 flex-wrap" style="margin-bottom: @(editCompact ? "0.25rem" : "0.75rem");">
                            <button class="btn btn-primary btn-sm">Primary</button>
                            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
                        </div>
                        <div class="preview-meta">
                            <small>
                                Theme: @editTheme · Font: @editFontSize ·
                                Language: @GetLanguageName(editLanguage) ·
                                Compact: @(editCompact ? "On" : "Off")
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompact;
    private bool saving;
    private string? statusMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !saving)
        {
            editTheme = Settings.Theme;
            editFontSize = Settings.FontSize;
            editLanguage = Settings.Language;
            editCompact = Settings.CompactMode;
        }
    }

    private string PreviewThemeClass => editTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewFontSize => editFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private static string GetLanguageName(string code) => code switch
    {
        "en" => "English",
        "es" => "Spanish",
        "fr" => "French",
        "de" => "German",
        "ja" => "Japanese",
        "zh" => "Chinese",
        "pt" => "Portuguese",
        _ => code
    };

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompact);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Appearance settings saved!";
        }
        finally
        {
            saving = false;
        }
    }
}

.preview-area {
    border-radius: 0.375rem;
    transition: all 0.2s ease;
    min-height: 200px;
}

.preview-light {
    background: #ffffff;
    color: #212529;
    border: 1px solid #dee2e6;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border: 1px solid #444;
}

.preview-dark .btn-primary {
    background: #5b8dee;
    border-color: #5b8dee;
}

.preview-dark .btn-outline-secondary {
    color: #adb5bd;
    border-color: #adb5bd;
}

