arguments.file_text:
@page "/settings"
@using sv_28f77283ea224006a73c7359a7b3a33d.Models
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="section => activeSection = section" />

    <div class="settings-content">
        @if (loading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                    break;

                case "Notifications":
                    <NotificationsSection Prefs="@notifPrefs"
                                          AvailableChannels="@availableChannels"
                                          OnSave="SaveNotificationsAsync" />
                    break;

                case "Security":
                    <SecuritySection Security="@security"
                                     CurrentSessionId="@currentSessionId"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;

                case "Appearance":
                    <AppearanceSection Settings="@appearance" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool loading = true;

    private UserProfile? profile;
    private NotificationPrefs? notifPrefs;
    private SecuritySettings? security;
    private AppearanceSettings? appearance;

    // Simulated current session id — first session is "current"
    private string currentSessionId = "";

    private List<string> availableChannels = new()
    {
        "General", "Announcements", "Engineering", "Design", "Marketing", "Support"
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        loading = false;
    }

    private async Task LoadAllAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        profile = profileTask.Result;
        notifPrefs = notifTask.Result;
        security = securityTask.Result;
        appearance = appearanceTask.Result;

        if (security?.Sessions.Count > 0)
        {
            currentSessionId = security.Sessions[0].Id;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notifPrefs = updated;
    }

    private async Task ChangePasswordAsync((string current, string newPwd) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPwd);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

